class Solution {
    public String longestPalindrome(String s) {
        int n = s.length();
        if (n < 2) return s;

        int bestStart = 0, bestLen = 1;
        for (int left = 0; left < n; left++) {
            for (int right = left; right < n; right++) {
                if (right - left + 1 > bestLen && isPal(s, left, right)) {
                    bestStart = left;
                    bestLen = right - left + 1;
                }
            }
        }
        return s.substring(bestStart, bestStart + bestLen);
    }

    private boolean isPal(String s, int l, int r) {
        while (l < r) {
            if (s.charAt(l) != s.charAt(r)) return false;
            l++;
            r--;
        }
        return true;
    }
}

class Solution {
    private int bestStart = 0, bestLen = 1;

    public String longestPalindrome(String s) {
        int n = s.length();
        if (n < 2) return s;

        for (int i = 0; i < n; i++) {
            expand(s, i, i);       // 奇数长度，中心是单个字符
            expand(s, i, i + 1);   // 偶数长度，中心是缝隙
        }
        return s.substring(bestStart, bestStart + bestLen);
    }

    private void expand(String s, int l, int r) {
        int n = s.length();
        while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
            if (r - l + 1 > bestLen) {
                bestStart = l;
                bestLen = r - l + 1;
            }
            l--;
            r++;
        }
    }
}

class Solution {
    public String longestPalindrome(String s) {
        if (s == null || s.length() < 1) return "";

        // 预处理：插入 # 使所有回文都变成奇数长度
        StringBuilder sb = new StringBuilder("^#");
        for (char c : s.toCharArray()) {
            sb.append(c).append("#");
        }
        sb.append("$");
        String t = sb.toString();
        int n = t.length();

        int[] p = new int[n];       // p[i] = 以 i 为中心的回文半径
        int C = 0, R = 0;           // 当前最右回文的中心与右边界
        int maxLen = 0, center = 0;

        for (int i = 1; i < n - 1; i++) {
            // 在 R 之内可以借用对称点的半径
            if (i < R) {
                p[i] = Math.min(R - i, p[2 * C - i]);
            }
            // 只有超出 R 的部分才真正扩张
            while (t.charAt(i + p[i] + 1) == t.charAt(i - p[i] - 1)) {
                p[i]++;
            }
            // 更新最右边界
            if (i + p[i] > R) {
                C = i;
                R = i + p[i];
            }
            if (p[i] > maxLen) {
                maxLen = p[i];
                center = i;
            }
        }

        int start = (center - maxLen) / 2;
        return s.substring(start, start + maxLen);
    }
}
